create or replace view public.v_deal with (security_invoker = true) as
select
  e.id,
  e.number,
  e.status,
  e.summary,
  e.created_at,
  e.submitted_at,
  e.updated_at,
  e.data->>'MONTH' as month,
  nullif(e.data->>'DATECREATED','')::date as datecreated,
  e.data->'COLLECTIONLOCATION' as collectionlocation,
  e.data->>'QUOTENO' as quoteno,
  e.data->>'SALESREP' as salesrep,
  (select count(*) from public.entry_files ef where ef.entry_id = e.id and ef.field_key = 'POP') as pop_count,
  e.data->>'PARTNO1' as partno1,
  e.data->>'LINE1' as line1,
  e.data->>'PARTNO2' as partno2,
  e.data->>'LINE2' as line2,
  e.data->>'PARTNO3' as partno3,
  e.data->>'LINE3' as line3,
  e.data->>'PARTNO4' as partno4,
  e.data->>'LINE4' as line4,
  e.data->>'PARTNO5' as partno5,
  e.data->>'LINE5' as line5,
  e.data->>'PARTNO6' as partno6,
  e.data->>'LINE6' as line6,
  e.data->>'PARTNO7' as partno7,
  e.data->>'LINE7' as line7,
  e.data->>'PARTNO8' as partno8,
  e.data->>'LINE8' as line8,
  nullif(e.data->>'Total','')::numeric as total
from public.entries e join public.forms f on f.id = e.form_id
where f.slug = 'deal';

